body:
I found a related failure on an Apple M2 Pro using Metal, with a custom Godot 4.8-dev build based on `b56a91878`.

The bake completed but left black rectangular patches. Adding command-buffer error logging exposed:

```text
Impacting Interactivity (0000000e:kIOGPUCommandBufferCallbackErrorImpactingInteractivity)
```

macOS was cancelling GPU work, leaving parts of the lightmap unwritten.

Limiting only the direct-light pass to 32 × 32 regions fixed this scene. I kept indirect regions at 128 × 128 with `max_rays_per_pass = 4`; reducing all regions to 32 made indirect baking much slower.

The full bake completed at High quality (512 rays) without Metal command-buffer errors, and the black patches disappeared. This run also used `--disable-render-loop` to avoid editor redraws during baking.

These are the two local diffs:

<details>
<summary>Log Metal command-buffer failures</summary>

```diff
diff --git a/drivers/metal/metal3_objects.cpp b/drivers/metal/metal3_objects.cpp
--- a/drivers/metal/metal3_objects.cpp
+++ b/drivers/metal/metal3_objects.cpp
@@ -122,6 +122,11 @@ void MDCommandBuffer::commit() {
 			_frame_state.rs->commit();
 		}
 	}
+	commandBuffer->addCompletedHandler([](MTL::CommandBuffer *p_command_buffer) {
+		if (p_command_buffer->error() != nullptr) {
+			ERR_PRINT(String("Metal command buffer failed: ") + p_command_buffer->error()->localizedDescription()->utf8String());
+		}
+	});
 	commandBuffer->commit();
 	commandBuffer.reset();
 	state_begin = false;
```

</details>

<details>
<summary>Use smaller regions for the direct-light pass on Metal</summary>

```diff
diff --git a/modules/lightmapper_rd/lightmapper_rd.cpp b/modules/lightmapper_rd/lightmapper_rd.cpp
--- a/modules/lightmapper_rd/lightmapper_rd.cpp
+++ b/modules/lightmapper_rd/lightmapper_rd.cpp
@@ -1848,16 +1848,20 @@

 		RID light_uniform_set = rd->uniform_set_create(uniforms, compute_shader_primary, 1);

+		// The direct pass traces all samples at once, so keep Metal command buffers short.
+		const int direct_region_size = rd->get_device_api_name() == "Metal" ? MIN(max_region_size, 32) : max_region_size;
+		const int direct_x_regions = Math::division_round_up(atlas_size.width, direct_region_size);
+		const int direct_y_regions = Math::division_round_up(atlas_size.height, direct_region_size);
 		int count = 0;
 		for (int s = 0; s < atlas_slices; s++) {
 			push_constant.atlas_slice = s;

-			for (int i = 0; i < x_regions; i++) {
-				for (int j = 0; j < y_regions; j++) {
-					int x = i * max_region_size;
-					int y = j * max_region_size;
-					int w = MIN((i + 1) * max_region_size, atlas_size.width) - x;
-					int h = MIN((j + 1) * max_region_size, atlas_size.height) - y;
+			for (int i = 0; i < direct_x_regions; i++) {
+				for (int j = 0; j < direct_y_regions; j++) {
+					int x = i * direct_region_size;
+					int y = j * direct_region_size;
+					int w = MIN((i + 1) * direct_region_size, atlas_size.width) - x;
+					int h = MIN((j + 1) * direct_region_size, atlas_size.height) - y;

 					push_constant.region_ofs[0] = x;
 					push_constant.region_ofs[1] = y;
@@ -1876,7 +1880,7 @@

 					count++;
 					if (p_step_function) {
-						int total = (atlas_slices * x_regions * y_regions);
+						int total = (atlas_slices * direct_x_regions * direct_y_regions);
 						int percent = count * 100 / total;
 						float p = float(count) / total * 0.1;
 						if (p_step_function(0.5 + p, vformat(RTR("Plot direct lighting %d%%"), percent), p_bake_userdata, false)) {
```

</details>
